# Change-set definitions for the hard seeded-defect benchmark (answer key source).
# Each edit is an exact-once text replacement on a copy of the clean system, or a new file.
O = "things/webapp/ontology.yaml"
S = "things/webapp/spec.yaml"
TC = "things/webapp/criteria.yaml"
SC = "criteria.yaml"
D = "description.yaml"
X = "externals.yaml"
def J(n): return f"journeys/J.{n}.yaml"
def E(n): return f"evolutions/evolution.{n}.yaml"
def R(file, old, new, desc): return {"file": file, "old": old, "new": new, "description": desc}
def NEW(file, content, desc): return {"file": file, "create": content, "description": desc}

